async function main() {
  console.log(`Uploading ${RATIONALES.length} AI rationales to pick_ai_rationales…\n`);

  for (const r of RATIONALES) {
    const { fund_code, fund_name, category, rank, analysis } = r;
    const { error } = await supabase
      .from("pick_ai_rationales")
      .upsert(
        { fund_code, fund_name, category, rank, analysis, generated_at: GENERATED_AT },
        { onConflict: "fund_code" }
      );

    if (error) {
      console.error(`  ✗ #${rank} ${fund_name}: ${error.message}`);
    } else {
      console.log(`  ✓ #${rank} ${fund_name} (${category}) → ${analysis.verdict} [${analysis.confidence}]`);
    }
  }

  console.log(`\nDone. ${RATIONALES.length} AI rationales written.`);
}

main().catch((e) => { console.error("FATAL:", e.message); process.exit(1); });
